def is_prime(n: int) -> bool:
    """Return True if n is a prime number."""
    # Check if n is less than 2
    if n < 2:
        return False
    # Check for factors from 2 to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    # If no factors were found, n is prime
    return True

