def first_unique_char(s: str) -> int:
    """Return the index of the first character that appears exactly once in s, or -1."""
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char, count in char_count.items():
        if count == 1:
            return s.index(char)

    return -1
